function T = validate_sws_risk_coverage(phantom_cases)
%VALIDATE_SWS_RISK_COVERAGE Compare THREE quality metrics at equal coverage.
%
% IMPORTANT: THIS IS A VALIDATION TEST, NOT A NEW QUALITY METRIC.
% Ground truth is used only to measure the error of accepted SWS estimates.
% Quality rankings use ground-truth-independent maps computed earlier:
%  (1) Correlation Q (adapted, Schoen et al.)
%  (2) Phase Planarity Q (our experimental candidate)
%  (3) RMI-1D (adapted Choi et al. 2015, Eq. 6)
%
% INPUTS PER PHANTOM (generated by previous scripts):
% Results/sws_measurement_quality/<phantom>/phase_consistency_diagnostic/
%   phase_quality_results.mat (Qold, Qphase)
% Results/sws_measurement_quality/<phantom>/rmi_1d_diagnostic/
%   rmi_1d_results.mat (RmiPG, RmiAC, basic, masks, regions, GT, cPG, cAC, x, z)
%
% INSTALL: Place this file in the project's Analysis/ folder.
% RUN ALL FOUR (recommended):
%   validate_sws_risk_coverage()
% OR ONE:
%   validate_sws_risk_coverage('large_inclusions')
%
% LOGIC:
% For each coverage fraction, keep the TOP fraction by quality Q.
% Risk is mean absolute SWS error among accepted samples, in m/s.
% Lower risk is better. Random baseline = full-region MAE.
% Oracle = rank by ground-truth error (evaluation-only ideal, unattainable
% without GT). For tied quality scores we distribute the boundary group
% fractionally, returning EXPECTED risk under unbiased random tie-breaking.
% This is critical for Correlation Q where a very large fraction equals 1.
%
% Two evaluation units:
%   Pixel: each pixel receives equal weight (NOT statistically independent).
%   Block: fixed 1-mm spatial block means; each block receives equal weight.
% Both are computed on exactly the saved 'basic' common pixel mask.
% Region masks are the same as used in validate_sws_rmi.m.
%
% AURC = normalized trapezoidal integral of Risk(Coverage) from 5% to 100%.
% AURC_ratio = AURC / random-baseline risk. Below 1 is better than random.
% Block AURC is descriptive, NOT an independent-sample significance test.
%
% PER-PHANTOM OUTPUTS:
% Results/sws_measurement_quality/<phantom>/risk_coverage_diagnostic/
%   risk_coverage_global.png, risk_coverage_regions.png,
%   risk_coverage_summary.csv, risk_coverage_curves.csv,
%   risk_coverage_results.mat
% BATCH OUTPUTS:
% Results/sws_measurement_quality/risk_coverage_all_phantoms.csv
% Results/sws_measurement_quality/risk_coverage_overview.png
%
% MATLAB: R2020b+ (tiledlayout, exportgraphics, string, tables).

    if nargin < 1 || isempty(phantom_cases)
        phantom_cases = ["large_inclusions", "high_contrast", ...
            "low_contrast", "chaoran_baseline"];
    end
    phantom_cases = string(phantom_cases);
    phantom_cases = phantom_cases(:);  % accept char or string arrays

    here = fileparts(mfilename('fullpath'));
    if isfolder(fullfile(here,'Results'))
        repo = here;
    else
        repo = fileparts(here);
    end
    result_root = fullfile(repo,'Results','sws_measurement_quality');
    assert(isfolder(result_root), 'Missing Results/sws_measurement_quality folder.');

    coverage = (0.05:0.05:1.00)';  % no coverage=0 (undefined risk)
    block_mm = 1.0;
    metric_names = ["Correlation Q", "Phase Planarity Q", "RMI-1D"];
    methods = ["PG", "AC"];
    units = ["Pixel", "Block1mm"];
    T = table();
    self_test_risk_curve();  % ensure tie handling and full-coverage invariants

    for pi = 1:numel(phantom_cases)
        p = char(phantom_cases(pi));
        fprintf('\n===== RISK-COVERAGE VALIDATION: %s =====\n',p);
        pdir = fullfile(result_root,p);
        rmi_file = fullfile(pdir,'rmi_1d_diagnostic','rmi_1d_results.mat');
        phase_file = fullfile(pdir,'phase_consistency_diagnostic', ...
            'phase_quality_results.mat');
        assert(isfile(rmi_file), 'Missing RMI result: %s',rmi_file);
        assert(isfile(phase_file), 'Missing phase Q result: %s',phase_file);

        R = load(rmi_file,'RmiPG','RmiAC','GT','cPG','cAC', ...
            'basic','masks','regions','x','z');
        P = load(phase_file,'Qold','Qphase');
        q0 = double(P.Qold);
        q1 = double(P.Qphase);
        qR = {double(R.RmiPG),double(R.RmiAC)};
        c = {double(R.cPG),double(R.cAC)};
        GT = double(R.GT);
        base = logical(R.basic);
        sz = size(GT);
        assert(isequal(size(q0),sz,size(q1),size(qR{1}), ...
            size(qR{2}),size(c{1}),size(c{2}),size(base)), ...
            'Saved map dimensions do not match; regenerate prerequisite data.');
        assert(numel(R.masks)==numel(R.regions), ...
            'Regions do not match saved RMI region masks.');
        assert(numel(R.x)==sz(2) && numel(R.z)==sz(1), ...
            'Coordinate axes have wrong lengths.');

        [X,Z] = meshgrid(double(R.x(:)),double(R.z(:)));
        bx = floor((X - min(X(:)))/(block_mm*1e-3));
        bz = floor((Z - min(Z(:)))/(block_mm*1e-3));
        spatial_block_id = bz*(max(bx(:))+1) + bx + 1;
        clear X Z bx bz;

        rows = table();
        curves = table();
        for ri = 1:numel(R.regions)
            region = string(R.regions{ri});
            mask = logical(R.masks{ri}) & base;
            assert(nnz(mask)>0,'No shared valid pixels in %s.',region);
            block_ids = spatial_block_id(mask);
            for mi = 1:2
                error_map = abs(c{mi}-GT);
                e = error_map(mask);
                qs = {q0(mask),q1(mask),qR{mi}(mask)};
                assert(all(isfinite(e)) && all(cellfun(@(v) all(isfinite(v)),qs)), ...
                    'Non-finite data within common mask: %s, %s.',p,region);
                oracle_pixel = risk_curve(-e,e,coverage);
                for qi = 1:3
                    q = qs{qi};
                    for ui = 1:2
                        if ui == 1
                            qq = q;
                            ee = e;
                            oracle = oracle_pixel;
                        else
                            [qq,ee] = block_means(block_ids,q,e);
                            oracle = risk_curve(-ee,ee,coverage);
                        end
                        risk = risk_curve(qq,ee,coverage);
                        random_risk = mean(ee);
                        assert(abs(risk(end)-random_risk) < ...
                            1e-9*max(1,random_risk), ...
                            'Risk at 100%% must equal full-region MAE.');
                        aurc = trapz(coverage,risk)/(coverage(end)-coverage(1));
                        if random_risk > 0
                            ratio = aurc/random_risk;
                            gain50 = 100*(1-risk_at(coverage,risk,0.50)/random_risk);
                        else
                            ratio = NaN;
                            gain50 = NaN;
                        end
                        row = table(string(p),region,methods(mi), ...
                            metric_names(qi),units(ui),numel(ee), ...
                            nnz(mask),random_risk,aurc,ratio, ...
                            risk_at(coverage,risk,0.20), ...
                            risk_at(coverage,risk,0.50), ...
                            risk_at(coverage,risk,0.80),gain50, ...
                            'VariableNames',{'Phantom','Region','Estimator', ...
                            'Metric','Unit','N_Units','N_Pixels', ...
                            'RandomRisk_mps','AURC_mps','AURC_over_Random', ...
                            'Risk20_mps','Risk50_mps','Risk80_mps', ...
                            'RiskReduction50_pct'});
                        rows = [rows;row]; %#ok<AGROW>
                        n = numel(coverage);
                        add = table(repmat(string(p),n,1), ...
                            repmat(region,n,1),repmat(methods(mi),n,1), ...
                            repmat(metric_names(qi),n,1), ...
                            repmat(units(ui),n,1),coverage*100,risk, ...
                            repmat(random_risk,n,1),oracle, ...
                            'VariableNames',{'Phantom','Region','Estimator', ...
                            'Metric','Unit','Coverage_pct','RiskMAE_mps', ...
                            'RandomRisk_mps','OracleRisk_mps'});
                        curves = [curves;add]; %#ok<AGROW>
                    end
                end
            end
        end
        outdir = fullfile(pdir,'risk_coverage_diagnostic');
        if ~isfolder(outdir), mkdir(outdir); end
        writetable(rows,fullfile(outdir,'risk_coverage_summary.csv'));
        writetable(curves,fullfile(outdir,'risk_coverage_curves.csv'));
        save(fullfile(outdir,'risk_coverage_results.mat'), ...
            'rows','curves','coverage','block_mm','metric_names', ...
            'methods','units');

        make_global_plot(curves,p,outdir,coverage,metric_names,methods,units);
        make_regional_plot(curves,p,outdir,coverage,metric_names,methods);
        fprintf('Common pixels, global: %d\n',nnz(R.masks{1} & base));
        fprintf('Summary, global pixel risk-coverage (smaller AURC ratio is better):\n');
        ix = rows.Region=="Global" & rows.Unit=="Pixel";
        disp(rows(ix,{'Estimator','Metric','AURC_over_Random', ...
            'Risk20_mps','Risk50_mps','Risk80_mps'}));
        fprintf('Saved to: %s\n',outdir);
        T = [T;rows]; %#ok<AGROW>
    end

    if numel(phantom_cases)>1
        writetable(T,fullfile(result_root,'risk_coverage_all_phantoms.csv'));
        make_overview_plot(T,result_root,phantom_cases,metric_names,methods);
        fprintf('Combined outputs saved to %s\n',result_root);
    end
    fprintf(['NOTE: This evaluates acceptance RISK using ground truth; it ' ...
        'does NOT introduce another quality metric.\n']);
    fprintf(['Tie-aware fractional inclusion used at Q thresholds. ' ...
        'Pixel samples are spatially correlated.\n']);
end

function risk = risk_curve(q,e,coverage)
% Equal-fraction acceptance with UNBIASED treatment of tied Q values.
% If a coverage cut lies within a Q plateau, include an equal fraction
% of every tied sample. Expected error is then the group's mean error.
    q = double(q(:));
    e = double(e(:));
    assert(numel(q)==numel(e) && ~isempty(q), ...
        'Quality and error vectors must be nonempty and equal in size.');
    assert(all(isfinite(q)) && all(isfinite(e)) && all(e>=0), ...
        'All scores/errors must be finite; errors must be nonnegative.');
    [qsort,order] = sort(q,'descend');
    esort = e(order);
    newgroup = [true; diff(qsort)~=0];
    groupid = cumsum(newgroup);
    ng = groupid(end);
    counts = accumarray(groupid,1,[ng,1]);
    err_sums = accumarray(groupid,esort,[ng,1]);
    cum_n = cumsum(counts);
    cum_e = cumsum(err_sums);
    n = numel(q);
    risk = zeros(size(coverage));
    for k=1:numel(coverage)
        wanted = double(coverage(k))*n;
        g = find(cum_n>=wanted-1e-8,1,'first');
        if isempty(g), g=ng; end
        if g==1, prev_n=0; prev_e=0;
        else, prev_n=cum_n(g-1); prev_e=cum_e(g-1); end
        n_in_group = max(0, min(counts(g),wanted-prev_n));
        risk(k) = (prev_e+n_in_group*err_sums(g)/counts(g))/wanted;
    end
end

function [qm,em] = block_means(block_id,q,e)
% Equal weighting of valid 1-mm spatial blocks (not equal pixels).
    [~,~,g] = unique(double(block_id(:)));
    n = accumarray(g,1);
    qm = accumarray(g,double(q(:)))./n;
    em = accumarray(g,double(e(:)))./n;
end

function value = risk_at(coverage,risk,f)
    [d,i] = min(abs(coverage-f));
    assert(d<1e-8,'Target coverage not found.');
    value = risk(i);
end

function make_global_plot(C,p,outdir,coverage,metric_names,methods,units)
    f=figure('Color','w','Name',['Risk-coverage: ' strrep(p,'_',' ')]);
    tl=tiledlayout(f,2,2,'TileSpacing','compact','Padding','compact');
    for ui=1:2
        for mi=1:2
            ax=nexttile(tl);
            hold(ax,'on');
            subset=C.Region=="Global" & C.Unit==units(ui) & ...
                C.Estimator==methods(mi);
            for qi=1:3
                s=C(subset & C.Metric==metric_names(qi),:);
                assert(height(s)==numel(coverage),'Incomplete saved coverage rows.');
                plot(ax,s.Coverage_pct,s.RiskMAE_mps,'LineWidth',1.8, ...
                    'DisplayName',char(metric_names(qi)));
            end
            s=C(subset & C.Metric==metric_names(1),:);
            plot(ax,s.Coverage_pct,s.RandomRisk_mps,'k--', ...
                'LineWidth',1.1,'DisplayName','Random baseline');
            plot(ax,s.Coverage_pct,s.OracleRisk_mps,'k:', ...
                'LineWidth',1.4,'DisplayName','Oracle (GT only)');
            title(ax,sprintf('%s / %s',methods(mi),units(ui)), ...
                'Interpreter','none');
            xlabel(ax,'Accepted coverage [%]');
            ylabel(ax,'Accepted MAE [m/s]');
            xlim(ax,[5 100]); grid(ax,'on');
            if ui==1 && mi==1,legend(ax,'Location','best');end
        end
    end
    title(tl,['Risk-coverage | ' strrep(p,'_',' ') ' | lower is better']);
    exportgraphics(f,fullfile(outdir,'risk_coverage_global.png'),'Resolution',180);
end

function make_regional_plot(C,p,outdir,coverage,metric_names,methods)
    regs=["InclusionCore","BackgroundInterior","LateralBoundary"];
    f=figure('Color','w','Name',['Regional risk-coverage: ' strrep(p,'_',' ')]);
    tl=tiledlayout(f,3,2,'TileSpacing','compact','Padding','compact');
    for ri=1:3
        for mi=1:2
            ax=nexttile(tl);
            hold(ax,'on');
            selector=C.Region==regs(ri) & C.Estimator==methods(mi) & ...
                C.Unit=="Pixel";
            for qi=1:3
                s=C(selector & C.Metric==metric_names(qi),:);
                assert(height(s)==numel(coverage),'Missing regional coverage rows.');
                plot(ax,s.Coverage_pct,s.RiskMAE_mps,'LineWidth',1.6, ...
                    'DisplayName',char(metric_names(qi)));
            end
            s=C(selector & C.Metric==metric_names(1),:);
            plot(ax,s.Coverage_pct,s.RandomRisk_mps,'k--', ...
                'DisplayName','Random baseline');
            title(ax,sprintf('%s / %s',regs(ri),methods(mi)), ...
                'Interpreter','none');
            xlabel(ax,'Accepted coverage [%]');
            ylabel(ax,'Accepted MAE [m/s]');
            xlim(ax,[5 100]); grid(ax,'on');
            if ri==1 && mi==1,legend(ax,'Location','best');end
        end
    end
    title(tl,['Regional pixel risk-coverage | ' strrep(p,'_',' ')]);
    exportgraphics(f,fullfile(outdir,'risk_coverage_regions.png'),'Resolution',180);
end

function make_overview_plot(T,result_root,phantom_cases,metric_names,methods)
    f=figure('Color','w','Name','Risk-coverage: four-phantom overview');
    tl=tiledlayout(f,1,2,'TileSpacing','compact','Padding','compact');
    for mi=1:2
        ax=nexttile(tl);
        vals=nan(numel(phantom_cases),numel(metric_names));
        for pi=1:numel(phantom_cases)
            for qi=1:numel(metric_names)
                idx=T.Phantom==phantom_cases(pi) & T.Region=="Global" & ...
                    T.Unit=="Pixel" & T.Estimator==methods(mi) & ...
                    T.Metric==metric_names(qi);
                assert(nnz(idx)==1,'Missing overview value.');
                vals(pi,qi)=T.AURC_over_Random(idx);
            end
        end
        bar(ax,vals);
        yline(ax,1,'k--','Random ranking');
        ylabel(ax,'AURC / random AURC (lower is better)');
        title(ax,char(methods(mi)));
        set(ax,'XTick',1:numel(phantom_cases), ...
            'XTickLabel',strrep(cellstr(phantom_cases),'_',' '));
        xtickangle(ax,20); grid(ax,'on');
        if mi==1,legend(ax,cellstr(metric_names),'Location','best');end
    end
    title(tl,'Global pixel risk-coverage across phantoms');
    exportgraphics(f,fullfile(result_root,'risk_coverage_overview.png'), ...
        'Resolution',180);
end

function self_test_risk_curve()
% Ties must be averaged fairly, not broken by original array order.
    c = [0.25; 0.50; 1.00];
    e = [0; 2; 9; 9];
    q = [1; 1; 0; 0];
    r = risk_curve(q,e,c);
    assert(max(abs(r-[1;1;5])) < 1e-12, ...
        'Risk-coverage tie handling failed self-test.');
    r2 = risk_curve(flipud(q),flipud(e),c);
    assert(max(abs(r-r2)) < 1e-12, ...
        'Tie handling depends on input order.');
    assert(abs(risk_curve([4;3;2;1],[1;2;3;4],1)-2.5)<1e-12, ...
        'Full-coverage risk sanity check failed.');
end
